  "updated_constraints": [
    {"text": "首批只做100件试水，卖得动才开第二批", "source": "map_caogen_16"},
    {"text": "账上必须留现金保工资，不能压太多货", "source": "map_caogen_20"},
    {"text": "达人合作先找本地熟人推荐，不花大钱铺量", "source": "map_caogen_40"},
    {"text": "成本每省下一块，都是自己挣的一块，包装和物料用熟悉供应商", "source": "map_caogen_49"},
    {"text": "账期从90天谈到45天，现金一下宽松许多", "source": "map_caogen_18"}
  ]
}

